import java.math.*;import java.time.*;import java.util.*;import java.lang.reflect.*;import java.nio.file.*;
import com.hrm.dto.*;import com.hrm.model.*;import com.hrm.enums.*;import com.hrm.repository.*;import com.hrm.service.*;import com.hrm.service.engine.*;import tools.jackson.databind.json.JsonMapper;
public class PayrollPolicyProbe {
 public static void main(String[] args)throws Exception{
  var mapper=JsonMapper.builder().build();var result=new LinkedHashMap<String,Object>();
  var components=new ArrayList<SalaryComponent>();for(String code:List.of("LUONG_CONG","TANG_CA","PHU_CAP","KHAU_TRU")){var c=new SalaryComponent(code,code,code.equals("KHAU_TRU")?SalaryComponentDirection.DEDUCT:SalaryComponentDirection.ADD,true);c.setComponentId((long)components.size()+1);components.add(c);}
  SalaryComponentRepository repo=(SalaryComponentRepository)Proxy.newProxyInstance(PayrollPolicyProbe.class.getClassLoader(),new Class[]{SalaryComponentRepository.class},(p,m,a)->{if(m.getName().equals("findAll"))return components;if(m.getName().equals("toString"))return "QA component fixture";throw new UnsupportedOperationException(m.getName());});
  var engine=new PayrollCalculationEngine(repo);var rows=new ArrayList<Object>();
  String[][] cases={{"TC-01","15000000","21","1","4.5","730000","500000","THANG"},{"TC-02","8000000","22","0","0","0","0","THANG"},{"TC-03","30000000","22","0","0","0","0","THANG"},{"TC-04","15000000","11","0","0","0","0","THANG"},{"TC-05","22000000","22","0","8","0","0","THANG"},{"TC-06","10000000","22","0","0","800000","0","THANG"},{"TC-07","20000000","22","0","0","0","0","THANG"},{"TC-08","60000000","22","0","0","0","0","THANG"},{"MEAL-CAP-01","15000000","22","0","0","800000","0","THANG"},{"DAILY-01","1000000","22","0","0","0","0","NGAY"},{"HOURLY-01","100000","22","0","0","0","0","GIO"}};
  EmployeeSalaryProfileDTO last=null;AttendanceSummaryDTO attendance=null;
  for(var c:cases){var p=new EmployeeSalaryProfileDTO();p.setEmployeeId(1L);p.setEmployeeCode("QA_ENGINE");p.setFullName("QA quote \" newline\n");p.setBaseSalary(new BigDecimal(c[1]));p.setPayBasis(c[7]);p.setAllowances(List.of(new EmployeeSalaryProfileDTO.AllowanceItemDTO("AN_TRUA","QA lunch",new BigDecimal(c[5]),"THEO_KY"),new EmployeeSalaryProfileDTO.AllowanceItemDTO("DI_LAI","QA travel",new BigDecimal(c[6]),"THEO_KY")));
   attendance=new AttendanceSummaryDTO(1L,new BigDecimal("22"),new BigDecimal(c[2]),new BigDecimal(c[4]),new BigDecimal(c[3]),BigDecimal.ZERO);var lines=engine.calculatePayrollLines(1L,p,attendance);var evidence=new ArrayList<Object>();BigDecimal gross=BigDecimal.ZERO,deduct=BigDecimal.ZERO;
   for(var l:lines){evidence.add(Map.of("code",l.getComponentCodeSnapshot(),"direction",l.getDirectionSnapshot(),"amount",l.getAmount(),"explanation",l.getExplanation()));if(l.getDirectionSnapshot().equals("DEDUCT"))deduct=deduct.add(l.getAmount());else gross=gross.add(l.getAmount());}
   rows.add(Map.of("case",c[0],"input",c,"gross",gross,"deduct",deduct,"net",gross.subtract(deduct),"lines",evidence));last=p;
  }
  result.put("engineCases",rows);var boundaries=new ArrayList<Object>();var start=LocalDateTime.of(2026,11,4,9,0);for(int offset:new int[]{-31,-30,-16,-15,0,15,16}){var d=AttendanceClockPolicy.checkIn(start,start.plusHours(8),start.plusMinutes(offset));boundaries.add(Map.of("offsetMinutes",offset,"allowed",d.allowed(),"lateMinutes",d.lateMinutes()));}result.put("clock",boundaries);
  var service=new PayrollExecutionService(null,null,null,null,null,null,null,engine);var method=PayrollExecutionService.class.getDeclaredMethod("buildSnapshotJson",EmployeeSalaryProfileDTO.class,AttendanceSummaryDTO.class);method.setAccessible(true);String snapshot=(String)method.invoke(service,last,attendance);boolean valid;try{mapper.readValue(snapshot,Object.class);valid=true;}catch(RuntimeException ex){valid=false;}result.put("snapshotWithQuotesValid",valid);result.put("snapshotWithQuotes",snapshot);
  var missingRepo=(SalaryComponentRepository)Proxy.newProxyInstance(PayrollPolicyProbe.class.getClassLoader(),new Class[]{SalaryComponentRepository.class},(p,m,a)->m.getName().equals("findAll")?List.of():null);var missingEngine=new PayrollCalculationEngine(missingRepo);result.put("missingComponentsProducesLines",missingEngine.calculatePayrollLines(1L,last,attendance).size());
  Files.writeString(Path.of(args[0]),mapper.writerWithDefaultPrettyPrinter().writeValueAsString(result));System.out.println("Engine and policy probes completed; evidence contains synthetic QA data only.");
 }
}
